#include "algorithms/polar_alignment.h"
#include <opencv2/core.hpp>
#include <algorithm>
#include <cmath>

namespace oas { namespace {constexpr double PI=3.14159265358979323846,D=PI/180.0,R=180.0/PI;cv::Vec3d unit(double ra,double de){ra*=D;de*=D;return{std::cos(de)*std::cos(ra),std::cos(de)*std::sin(ra),std::sin(de)};}cv::Matx33d orient(const SolveResult&s){double ra=s.raDeg*D,de=s.decDeg*D,pa=s.rotationDeg*D;cv::Vec3d z=unit(s.raDeg,s.decDeg),east{-std::sin(ra),std::cos(ra),0},north{-std::sin(de)*std::cos(ra),-std::sin(de)*std::sin(ra),std::cos(de)};cv::Vec3d up=north*std::cos(pa)+east*std::sin(pa),right=east*std::cos(pa)-north*std::sin(pa),down=-up;return {right[0],down[0],z[0],right[1],down[1],z[1],right[2],down[2],z[2]};}cv::Vec3d axis(const cv::Matx33d&M){double angle=std::acos(std::clamp((M(0,0)+M(1,1)+M(2,2)-1.0)/2.0,-1.0,1.0));if(std::abs(std::sin(angle))<1e-8)return{0,0,0};cv::Vec3d v{M(2,1)-M(1,2),M(0,2)-M(2,0),M(1,0)-M(0,1)};double n=cv::norm(v);return n>1e-12?v*(1.0/n):cv::Vec3d{0,0,0};}double jd(const QDateTime&t){return t.toMSecsSinceEpoch()/86400000.0+2440587.5;}double gmst(const QDateTime&t){double j=jd(t),T=(j-2451545.0)/36525.0;double g=280.46061837+360.98564736629*(j-2451545.0)+0.000387933*T*T-T*T*T/38710000.0;return std::fmod(g+360.0,360.0);} }
PolarAlignmentResult PolarAlignmentEstimator::estimate(const std::vector<PolarSample>&s,const ObserverLocation&o,const QDateTime&utc)const{PolarAlignmentResult r;if(s.size()<2){r.message="At least two solved RA rotations are required";return r;}cv::Matx33d O0=orient(s[0].solve);cv::Vec3d sum{0,0,0};int n=0;for(size_t i=1;i<s.size();++i){cv::Matx33d Ri=orient(s[i].solve)*O0.t();cv::Vec3d a=axis(Ri);if(cv::norm(a)<0.5)continue;double d=s[i].mountRaDeg-s[0].mountRaDeg;while(d>180)d-=360;while(d<-180)d+=360;if(d<0)a=-a;if(a[2]<0)a=-a;sum+=a;++n;}if(!n||cv::norm(sum)<1e-6){r.message="Cannot estimate RA axis";return r;}cv::Vec3d a=sum*(1.0/cv::norm(sum));r.axisRaDeg=std::fmod(std::atan2(a[1],a[0])*R+360.0,360.0);r.axisDecDeg=std::asin(std::clamp(a[2],-1.0,1.0))*R;r.totalErrorArcmin=std::acos(std::clamp(a[2],-1.0,1.0))*R*60.0;double lat=o.latitudeDeg*D,theta=(gmst(utc)+o.longitudeDeg)*D;cv::Vec3d east{-std::sin(theta),std::cos(theta),0},north{-std::sin(lat)*std::cos(theta),-std::sin(lat)*std::sin(theta),std::cos(lat)},up{std::cos(lat)*std::cos(theta),std::cos(lat)*std::sin(theta),std::sin(lat)};double E=a.dot(east),N=a.dot(north),U=a.dot(up);double alt=std::asin(std::clamp(U,-1.0,1.0))*R,az=std::atan2(E,N)*R;r.altitudeAdjustmentArcmin=-(alt-o.latitudeDeg)*60.0;r.azimuthAdjustmentArcmin=-az*60.0;r.success=true;r.message="Adjust mount altitude and azimuth by the signed values";return r;}
}
